import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { helpers } from '../services/api';
import toast from '../utils/toast';
import '../styles/OrderConfirmation.css';

const OrderConfirmation = () => {
  const { orderId } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const [order, setOrder] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!user) {
      toast.warning('Please log in to view order');
      navigate('/login');
      return;
    }

    fetchOrderDetails();
  }, [user, orderId, navigate]);

  const fetchOrderDetails = async () => {
    try {
      setLoading(true);
      setError(null);

      const response = await fetch(`http://localhost:5001/api/orders/${orderId}`, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setOrder(data.order);
      } else {
        const errorData = await response.json();
        setError(errorData.error || 'Failed to load order');
        toast.error('Failed to load order details');
      }
    } catch (err) {
      console.error('Error fetching order:', err);
      setError('Failed to load order');
      toast.error('Failed to load order details');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="order-confirmation-page">
        <div className="loading">Loading order details...</div>
      </div>
    );
  }

  if (error || !order) {
    return (
      <div className="order-confirmation-page">
        <div className="error-container">
          <div className="error-icon">✕</div>
          <h2>Order Not Found</h2>
          <p>{error || 'Unable to load order details'}</p>
          <Link to="/products" className="btn-primary">
            Continue Shopping
          </Link>
        </div>
      </div>
    );
  }

  return (
    <div className="order-confirmation-page">
      <div className="confirmation-container">
        {/* Success Header */}
        <div className="success-header">
          <div className="success-icon">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
              <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"></path>
              <polyline points="22 4 12 14.01 9 11.01"></polyline>
            </svg>
          </div>
          <h1 className="success-title">Order Placed Successfully!</h1>
          <p className="success-subtitle">
            Thank you for your purchase. Your order has been confirmed.
          </p>
        </div>

        {/* Order Number */}
        <div className="order-number-section">
          <div className="order-number-label">Order Number</div>
          <div className="order-number">{order.order_number}</div>
          <div className="order-date">
            Placed on {new Date(order.created_at).toLocaleDateString('en-US', {
              weekday: 'long',
              year: 'numeric',
              month: 'long',
              day: 'numeric',
            })}
          </div>
        </div>

        {/* Email Confirmation Notice */}
        <div className="email-notice">
          <svg className="email-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
            <path d="M4 4h16c1.1 0 2 .9 2 2v12c0 1.1-.9 2-2 2H4c-1.1 0-2-.9-2-2V6c0-1.1.9-2 2-2z"></path>
            <polyline points="22,6 12,13 2,6"></polyline>
          </svg>
          <div className="email-notice-text">
            <strong>Confirmation email sent</strong>
            <p>We've sent a confirmation email to your registered email address with your order details.</p>
          </div>
        </div>

        <div className="confirmation-grid">
          {/* Left Column - Order Details */}
          <div className="order-details-section">
            {/* Order Items */}
            <div className="detail-card">
              <h2 className="card-title">Order Items</h2>
              <div className="order-items">
                {order.items && order.items.map((item) => (
                  <div key={item.id} className="order-item">
                    <img
                      src={item.product?.image_url}
                      alt={item.product?.name}
                      className="order-item-image"
                    />
                    <div className="order-item-details">
                      <h4 className="order-item-name">{item.product?.name}</h4>
                      <p className="order-item-variant">
                        Size: {item.variant?.size} | Color: {item.variant?.color}
                      </p>
                      <p className="order-item-quantity">Quantity: {item.quantity}</p>
                    </div>
                    <div className="order-item-price">
                      {helpers.formatPrice(item.total_price)}
                    </div>
                  </div>
                ))}
              </div>
            </div>

            {/* Shipping Address */}
            <div className="detail-card">
              <h2 className="card-title">Shipping Address</h2>
              <div className="address-content">
                {order.shipping_address && (
                  <>
                    <p>{order.shipping_address.street}</p>
                    <p>
                      {order.shipping_address.city}, {order.shipping_address.state} {order.shipping_address.zip}
                    </p>
                    <p>Phone: {order.shipping_address.phone}</p>
                  </>
                )}
              </div>
            </div>

            {/* Next Steps */}
            <div className="detail-card next-steps-card">
              <h2 className="card-title">What's Next?</h2>
              <div className="next-steps">
                <div className="next-step">
                  <div className="step-number">1</div>
                  <div className="step-content">
                    <h4>Order Processing</h4>
                    <p>We're preparing your items for shipment. You'll receive an update once your order is dispatched.</p>
                  </div>
                </div>
                <div className="next-step">
                  <div className="step-number">2</div>
                  <div className="step-content">
                    <h4>Shipping</h4>
                    <p>
                      {order.is_nairobi
                        ? 'Free shipping within Nairobi. Delivery within 2-3 business days.'
                        : 'Shipping to upcountry. Delivery within 5-7 business days.'}
                    </p>
                  </div>
                </div>
                <div className="next-step">
                  <div className="step-number">3</div>
                  <div className="step-content">
                    <h4>Delivery</h4>
                    <p>Track your order status in your order history. We'll notify you upon delivery.</p>
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* Right Column - Order Summary */}
          <div className="order-summary-section">
            <div className="summary-sticky">
              <div className="detail-card">
                <h2 className="card-title">Order Summary</h2>

                <div className="summary-row">
                  <span>Subtotal</span>
                  <span>{helpers.formatPrice(order.subtotal)}</span>
                </div>

                <div className="summary-row">
                  <span>Shipping</span>
                  <span>
                    {order.is_nairobi ? (
                      <span className="free-badge">FREE</span>
                    ) : (
                      helpers.formatPrice(order.shipping_cost)
                    )}
                  </span>
                </div>

                <div className="summary-row">
                  <span>Tax</span>
                  <span>{helpers.formatPrice(order.tax || 0)}</span>
                </div>

                <div className="summary-divider"></div>

                <div className="summary-row summary-total">
                  <span>Total</span>
                  <span className="total-amount">{helpers.formatPrice(order.total)}</span>
                </div>

                <div className="status-badge">
                  <span className={`badge badge-${order.status || 'pending'}`}>
                    {order.status ? (order.status.charAt(0).toUpperCase() + order.status.slice(1)) : 'Pending'}
                  </span>
                </div>
              </div>

              {/* Actions */}
              <div className="confirmation-actions">
                <Link to="/orders" className="btn-view-orders">
                  View Order History
                </Link>
                <Link to="/products" className="btn-continue-shopping">
                  Continue Shopping
                </Link>
              </div>

              {/* Return Policy Notice */}
              <div className="policy-notice">
                <svg className="info-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                  <circle cx="12" cy="12" r="10"></circle>
                  <line x1="12" y1="16" x2="12" y2="12"></line>
                  <line x1="12" y1="8" x2="12.01" y2="8"></line>
                </svg>
                <div className="policy-text">
                  <strong>Return Policy</strong>
                  <p>
                    Non-clearance items can be returned within 2 days of delivery.
                    A 10% restocking fee applies. FINAL SALE items cannot be returned.
                  </p>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default OrderConfirmation;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import { helpers } from '../services/api';
import toast from '../utils/toast';
import '../styles/OrderHistory.css';

const OrderHistory = () => {
  const navigate = useNavigate();
  const { user } = useAuth();
  const [orders, setOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [pagination, setPagination] = useState({
    page: 1,
    per_page: 10,
    total: 0,
    pages: 0,
  });
  const [filterStatus, setFilterStatus] = useState('all');

  useEffect(() => {
    if (!user) {
      toast.warning('Please log in to view order history');
      navigate('/login');
      return;
    }

    fetchOrders();
  }, [user, pagination.page, filterStatus, navigate]);

  const fetchOrders = async () => {
    try {
      setLoading(true);

      let url = `http://localhost:5001/api/orders?page=${pagination.page}&per_page=${pagination.per_page}`;

      if (filterStatus !== 'all') {
        url += `&status=${filterStatus}`;
      }

      const response = await fetch(url, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${localStorage.getItem('token')}`,
        },
      });

      if (response.ok) {
        const data = await response.json();
        setOrders(data.orders);
        setPagination({
          page: data.page,
          per_page: data.per_page,
          total: data.total,
          pages: data.pages,
        });
      } else {
        const errorData = await response.json();
        toast.error(errorData.error || 'Failed to load orders');
      }
    } catch (error) {
      console.error('Error fetching orders:', error);
      toast.error('Failed to load order history');
    } finally {
      setLoading(false);
    }
  };

  const handleViewOrder = (orderId) => {
    navigate(`/order-confirmation/${orderId}`);
  };

  const handlePageChange = (newPage) => {
    if (newPage >= 1 && newPage <= pagination.pages) {
      setPagination((prev) => ({ ...prev, page: newPage }));
      window.scrollTo({ top: 0, behavior: 'smooth' });
    }
  };

  const handleFilterChange = (status) => {
    setFilterStatus(status);
    setPagination((prev) => ({ ...prev, page: 1 }));
  };

  const getStatusBadgeClass = (status) => {
    return `status-badge badge-${status}`;
  };

  const formatDate = (dateString) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  };

  if (loading && orders.length === 0) {
    return (
      <div className="order-history-page">
        <div className="loading">Loading your orders...</div>
      </div>
    );
  }

  return (
    <div className="order-history-page">
      <div className="order-history-container">
        {/* Page Header */}
        <div className="page-header">
          <h1 className="page-title">Order History</h1>
          <p className="page-subtitle">
            View and track all your orders
          </p>
        </div>

        {/* Filter Tabs */}
        <div className="filter-tabs">
          <button
            className={`filter-tab ${filterStatus === 'all' ? 'active' : ''}`}
            onClick={() => handleFilterChange('all')}
          >
            All Orders
          </button>
          <button
            className={`filter-tab ${filterStatus === 'pending' ? 'active' : ''}`}
            onClick={() => handleFilterChange('pending')}
          >
            Pending
          </button>
          <button
            className={`filter-tab ${filterStatus === 'processing' ? 'active' : ''}`}
            onClick={() => handleFilterChange('processing')}
          >
            Processing
          </button>
          <button
            className={`filter-tab ${filterStatus === 'shipped' ? 'active' : ''}`}
            onClick={() => handleFilterChange('shipped')}
          >
            Shipped
          </button>
          <button
            className={`filter-tab ${filterStatus === 'delivered' ? 'active' : ''}`}
            onClick={() => handleFilterChange('delivered')}
          >
            Delivered
          </button>
        </div>

        {/* Orders List */}
        {orders.length === 0 ? (
          <div className="empty-state">
            <div className="empty-icon">
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                <rect x="1" y="4" width="22" height="16" rx="2" ry="2"></rect>
                <line x1="1" y1="10" x2="23" y2="10"></line>
              </svg>
            </div>
            <h2>No Orders Found</h2>
            <p>
              {filterStatus === 'all'
                ? "You haven't placed any orders yet."
                : `You don't have any ${filterStatus} orders.`}
            </p>
            <button
              className="btn-shop-now"
              onClick={() => navigate('/products')}
            >
              Start Shopping
            </button>
          </div>
        ) : (
          <>
            <div className="orders-list">
              {orders.map((order) => (
                <div
                  key={order.id}
                  className="order-card"
                  onClick={() => handleViewOrder(order.id)}
                >
                  <div className="order-card-header">
                    <div className="order-number">
                      <span className="label">Order Number:</span>
                      <span className="value">{order.order_number}</span>
                    </div>
                    <span className={getStatusBadgeClass(order.status)}>
                      {order.status.charAt(0).toUpperCase() + order.status.slice(1)}
                    </span>
                  </div>

                  <div className="order-card-body">
                    <div className="order-info-row">
                      <div className="info-item">
                        <svg className="info-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                          <circle cx="12" cy="12" r="10"></circle>
                          <polyline points="12 6 12 12 16 14"></polyline>
                        </svg>
                        <div>
                          <div className="info-label">Order Date</div>
                          <div className="info-value">{formatDate(order.created_at)}</div>
                        </div>
                      </div>

                      <div className="info-item">
                        <svg className="info-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                          <path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"></path>
                          <polyline points="3.27 6.96 12 12.01 20.73 6.96"></polyline>
                          <line x1="12" y1="22.08" x2="12" y2="12"></line>
                        </svg>
                        <div>
                          <div className="info-label">Items</div>
                          <div className="info-value">{order.items?.length || 0} items</div>
                        </div>
                      </div>

                      <div className="info-item">
                        <svg className="info-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                          <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"></path>
                          <circle cx="12" cy="7" r="4"></circle>
                        </svg>
                        <div>
                          <div className="info-label">Shipping</div>
                          <div className="info-value">
                            {order.is_nairobi ? 'Free (Nairobi)' : 'Upcountry'}
                          </div>
                        </div>
                      </div>
                    </div>

                    {/* Order Items Preview */}
                    {order.items && order.items.length > 0 && (
                      <div className="order-items-preview">
                        {order.items.slice(0, 3).map((item) => (
                          <img
                            key={item.id}
                            src={item.product?.image_url}
                            alt={item.product?.name}
                            className="item-thumbnail"
                          />
                        ))}
                        {order.items.length > 3 && (
                          <div className="more-items">
                            +{order.items.length - 3}
                          </div>
                        )}
                      </div>
                    )}
                  </div>

                  <div className="order-card-footer">
                    <div className="total-label">Total</div>
                    <div className="total-amount">{helpers.formatPrice(order.total)}</div>
                  </div>

                  <div className="view-details-arrow">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                      <polyline points="9 18 15 12 9 6"></polyline>
                    </svg>
                  </div>
                </div>
              ))}
            </div>

            {/* Pagination */}
            {pagination.pages > 1 && (
              <div className="pagination">
                <button
                  className="pagination-btn"
                  onClick={() => handlePageChange(pagination.page - 1)}
                  disabled={pagination.page === 1}
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <polyline points="15 18 9 12 15 6"></polyline>
                  </svg>
                  Previous
                </button>

                <div className="pagination-info">
                  Page {pagination.page} of {pagination.pages}
                  <span className="total-orders">({pagination.total} orders)</span>
                </div>

                <button
                  className="pagination-btn"
                  onClick={() => handlePageChange(pagination.page + 1)}
                  disabled={pagination.page === pagination.pages}
                >
                  Next
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2">
                    <polyline points="9 18 15 12 9 6"></polyline>
                  </svg>
                </button>
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default OrderHistory;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { productsAPI, helpers } from '../services/api';
import { useCart } from '../context/CartContext';
import { useWishlist } from '../context/WishlistContext';
import { useAuth } from '../context/AuthContext';
import toast from '../utils/toast';
import '../styles/ProductDetail.css';

const ProductDetail = () => {
  const { slug } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const { addToCart } = useCart();
  const { addToWishlist, isInWishlist } = useWishlist();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedSize, setSelectedSize] = useState('');
  const [selectedColor, setSelectedColor] = useState('');
  const [selectedVariant, setSelectedVariant] = useState(null);
  const [quantity, setQuantity] = useState(1);
  const [addingToCart, setAddingToCart] = useState(false);
  const [addingToWishlist, setAddingToWishlist] = useState(false);

  useEffect(() => {
    fetchProduct();
  }, [slug]);

  useEffect(() => {
    if (product && selectedSize && selectedColor) {
      findVariant();
    }
  }, [selectedSize, selectedColor, product]);

  // Reset quantity to 1 when variant changes
  useEffect(() => {
    setQuantity(1);
  }, [selectedVariant]);

  const fetchProduct = async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await productsAPI.getBySlug(slug);
      const productData = response.data;
      setProduct(productData);

      // Set default selections from available sizes/colors
      if (productData.available_sizes && productData.available_sizes.length > 0) {
        setSelectedSize(productData.available_sizes[0]);
      }
      if (productData.available_colors && productData.available_colors.length > 0) {
        setSelectedColor(productData.available_colors[0]);
      }
    } catch (err) {
      setError('Failed to load product. Please try again.');
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  const findVariant = () => {
    if (!product || !product.variants) return;

    const variant = product.variants.find(
      (v) => v.size === selectedSize && v.color === selectedColor && v.is_active
    );

    setSelectedVariant(variant || null);
  };

  const getAvailabilityStatus = () => {
    if (!selectedVariant || !selectedVariant.inventory) {
      return {
        available: false,
        quantity: 0,
        status: 'Out of Stock',
        statusClass: 'out-of-stock',
      };
    }

    const availableQty = selectedVariant.inventory.available_quantity;
    const isLowStock = selectedVariant.inventory.is_low_stock;
    const isOutOfStock = selectedVariant.inventory.is_out_of_stock;

    if (isOutOfStock || availableQty === 0) {
      return {
        available: false,
        quantity: 0,
        status: 'Out of Stock',
        statusClass: 'out-of-stock',
      };
    }

    if (isLowStock) {
      return {
        available: true,
        quantity: availableQty,
        status: `Low Stock (${availableQty} left)`,
        statusClass: 'low-stock',
      };
    }

    return {
      available: true,
      quantity: availableQty,
      status: `In Stock (${availableQty} available)`,
      statusClass: 'in-stock',
    };
  };

  const handleQuantityChange = (newQuantity) => {
    const maxQuantity = availability.quantity || 1;

    // Ensure quantity is within valid range
    if (newQuantity < 1) {
      setQuantity(1);
    } else if (newQuantity > maxQuantity) {
      setQuantity(maxQuantity);
      toast.warning(`Maximum available quantity is ${maxQuantity}`);
    } else {
      setQuantity(newQuantity);
    }
  };

  const handleQuantityDecrease = () => {
    if (quantity > 1) {
      setQuantity(quantity - 1);
    }
  };

  const handleQuantityIncrease = () => {
    const maxQuantity = availability.quantity || 1;
    if (quantity < maxQuantity) {
      setQuantity(quantity + 1);
    } else {
      toast.warning(`Maximum available quantity is ${maxQuantity}`);
    }
  };

  const handleAddToCart = async () => {
    if (!user) {
      toast.warning('Please log in to add items to cart');
      navigate('/login');
      return;
    }

    if (!selectedVariant) {
      toast.warning('Please select size and color');
      return;
    }

    if (!availability.available) {
      toast.error('This variant is out of stock');
      return;
    }

    if (quantity < 1) {
      toast.error('Please select a valid quantity');
      return;
    }

    if (quantity > availability.quantity) {
      toast.error(`Only ${availability.quantity} items available`);
      return;
    }

    setAddingToCart(true);
    const result = await addToCart(selectedVariant.id, quantity);
    setAddingToCart(false);

    if (result.success) {
      toast.success(`Added ${quantity} item(s) to cart!`);
    } else {
      toast.error(result.error || 'Failed to add to cart');
    }
  };

  const handleAddToWishlist = async () => {
    if (!user) {
      toast.warning('Please log in to add items to wishlist');
      navigate('/login');
      return;
    }

    if (isInWishlist(product.id)) {
      toast.info('This item is already in your wishlist');
      return;
    }

    setAddingToWishlist(true);
    const result = await addToWishlist(product.id);
    setAddingToWishlist(false);

    if (result.success) {
      toast.success('Added to wishlist!');
    } else {
      toast.error(result.error || 'Failed to add to wishlist');
    }
  };

  if (loading) return <div className="loading">Loading product...</div>;
  if (error) return <div className="error">{error}</div>;
  if (!product) return <div className="error">Product not found</div>;

  const availability = getAvailabilityStatus();
  const isOnSale = helpers.isOnSale(product);
  const discountPercent = helpers.getDiscountPercent(product);
  const canReturn = helpers.canBeReturned(product);
  const returnMessage = helpers.getReturnPolicyMessage(product);

  return (
    <div className="product-detail">
      <div className="product-container">
        {/* Product Images */}
        <div className="product-image-section">
          {product.images && product.images.length > 0 ? (
            <img
              src={product.images.find((img) => img.is_primary)?.image_url || product.images[0].image_url}
              alt={product.name}
              className="product-image-large"
            />
          ) : (
            <div className="product-image-placeholder">No Image</div>
          )}

          {/* Additional images thumbnails - future enhancement */}
          {product.images && product.images.length > 1 && (
            <div className="product-thumbnails">
              {product.images.map((img) => (
                <img
                  key={img.id}
                  src={img.image_url}
                  alt={img.alt_text}
                  className="product-thumbnail"
                />
              ))}
            </div>
          )}
        </div>

        {/* Product Info */}
        <div className="product-info-section">
          {/* Badges */}
          <div className="product-badges">
            {product.is_clearance && (
              <span className="badge final-sale-badge">FINAL SALE</span>
            )}
            {isOnSale && !product.is_clearance && (
              <span className="badge sale-badge">{discountPercent}% OFF</span>
            )}
          </div>

          <h1 className="product-title">{product.name}</h1>
          <p className="product-category">{product.category_name}</p>

          {/* Price */}
          <div className="product-price-section">
            {isOnSale ? (
              <>
                <span className="product-price-sale">{helpers.formatPrice(product.sale_price)}</span>
                <span className="product-price-original">{helpers.formatPrice(product.price)}</span>
              </>
            ) : (
              <span className="product-price">{helpers.formatPrice(product.price)}</span>
            )}
          </div>

          {/* Description */}
          {product.description && (
            <div className="product-description">
              <p>{product.description}</p>
            </div>
          )}

          {/* Variant Selection */}
          <div className="product-options">
            {/* Size Selection */}
            {product.available_sizes && product.available_sizes.length > 0 && (
              <div className="option-group">
                <label className="option-label">
                  Size: <span className="selected-value">{selectedSize}</span>
                </label>
                <div className="size-options">
                  {product.available_sizes.map((size) => (
                    <button
                      key={size}
                      className={`size-button ${selectedSize === size ? 'active' : ''}`}
                      onClick={() => setSelectedSize(size)}
                    >
                      {size}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Color Selection */}
            {product.available_colors && product.available_colors.length > 0 && (
              <div className="option-group">
                <label className="option-label">
                  Color: <span className="selected-value">{selectedColor}</span>
                </label>
                <div className="color-options">
                  {product.available_colors.map((color) => (
                    <button
                      key={color}
                      className={`color-button ${selectedColor === color ? 'active' : ''}`}
                      onClick={() => setSelectedColor(color)}
                    >
                      {color}
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>

          {/* Availability */}
          {selectedVariant && (
            <div className="availability-section">
              <div className={`availability-status ${availability.statusClass}`}>
                <span className="status-icon">
                  {availability.available ? '✓' : '✕'}
                </span>
                <span className="status-text">{availability.status}</span>
              </div>
              {selectedVariant.sku && (
                <p className="variant-sku">SKU: {selectedVariant.sku}</p>
              )}
            </div>
          )}

          {/* Quantity Selector */}
          {selectedVariant && availability.available && (
            <div className="quantity-section">
              <label className="quantity-label">Quantity:</label>
              <div className="quantity-selector">
                <button
                  className="quantity-btn"
                  onClick={handleQuantityDecrease}
                  disabled={quantity <= 1}
                  aria-label="Decrease quantity"
                >
                  −
                </button>
                <input
                  type="number"
                  className="quantity-input"
                  value={quantity}
                  onChange={(e) => handleQuantityChange(parseInt(e.target.value) || 1)}
                  min="1"
                  max={availability.quantity}
                />
                <button
                  className="quantity-btn"
                  onClick={handleQuantityIncrease}
                  disabled={quantity >= availability.quantity}
                  aria-label="Increase quantity"
                >
                  +
                </button>
              </div>
            </div>
          )}

          {/* Add to Cart Button */}
          <div className="action-buttons">
            <button
              className="btn-primary-large"
              disabled={!availability.available || addingToCart}
              onClick={handleAddToCart}
            >
              {addingToCart ? 'Adding...' : availability.available ? 'Add to Cart' : 'Out of Stock'}
            </button>
            <button
              className="btn-wishlist"
              onClick={handleAddToWishlist}
              disabled={addingToWishlist || isInWishlist(product.id)}
              title={isInWishlist(product.id) ? 'Already in wishlist' : 'Add to wishlist'}
            >
              <svg className="heart-icon" viewBox="0 0 24 24" fill={isInWishlist(product.id) ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2">
                <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>
              </svg>
            </button>
          </div>

          {/* Return Policy */}
          <div className="return-policy-section">
            <div className={`return-policy-badge ${canReturn ? 'returnable' : 'final-sale'}`}>
              <span className="policy-icon">{canReturn ? 'ℹ' : '⚠'}</span>
              <span className="policy-text">{returnMessage}</span>
            </div>
            {canReturn && (
              <p className="policy-details" style={{ fontSize: '0.875rem', color: '#666', marginTop: '0.5rem' }}>
                2-day return window from delivery. 10% restocking fee applies.
              </p>
            )}
          </div>

          {/* Product Meta */}
          <div className="product-meta">
            <div className="meta-item">
              <strong>Category:</strong> {product.category_name}
            </div>
            {product.weight && (
              <div className="meta-item">
                <strong>Weight:</strong> {product.weight} kg
              </div>
            )}
            <div className="meta-item">
              <strong>Product ID:</strong> {product.id}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProductDetail;

